53 #include <limits>
54 
55 namespace Assimp {
56 namespace Math {
57 
62 template <typename IntegerType>
63 inline IntegerType gcd( IntegerType a, IntegerType b ) {
64     const IntegerType zero = (IntegerType)0;
65     while ( true ) {
66         if ( a == zero ) {
67             return b;
68         }
69         b %= a;
70 
71         if ( b == zero ) {
72             return a;
73         }
74         a %= b;
75     }
76 }
77 
82 template < typename IntegerType >
83 inline IntegerType lcm( IntegerType a, IntegerType b ) {
84     const IntegerType t = gcd (a,b);
85     if (!t) {
86         return t;
87     }
88     return a / t * b;
89 }
92 template<class T>
93 inline T getEpsilon() {
94     return std::numeric_limits<T>::epsilon();
95 }
96 
99 template<class T>
100 inline T aiPi() {
101     return static_cast<T>(3.14159265358979323846);
102 }
103 
104 } // namespace Math
